// <snippet:email-layout>
// Shared HTML email layout. Code nodes can't import files, so `npm run sync:n8n`
// copies this block into every node that renders an email; the unit tests fail
// if a copy drifts. Edit it here, never inside the workflow JSON.
const EMAIL_COLORS = {
  border: "#e2dbd1",
  card: "#fffefb",
  muted: "#6c6158",
  onPrimary: "#fdfaf3",
  page: "#fcf9f2",
  panel: "#f4efe7",
  primary: "#206040",
  text: "#2b2018",
};
const EMAIL_TONES = {
  bad: ["#fbe0df", "#9b1c1b"],
  good: ["#e4f1e6", "#123c27"],
  info: [EMAIL_COLORS.panel, EMAIL_COLORS.muted],
  warn: ["#fbe2d2", "#79371e"],
};
const SERIF = "Fraunces, Georgia, 'Times New Roman', serif";
const SANS = "-apple-system, 'Segoe UI', Helvetica, Arial, sans-serif";
const HTTP_URL = /^https?:\/\//iu;

const TRUSTED_LABEL = "Trusted lender";

function escapeHtml(value) {
  const entities = {
    "'": "&#39;",
    '"': "&quot;",
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
  };
  return String(value ?? "").replace(/[&<>"']/gu, (char) => entities[char]);
}

// "2026-11-02" -> "Mon 2 Nov 2026". Loan dates are UTC calendar days.
function formatDay(isoDay) {
  const date = new Date(`${isoDay}T00:00:00Z`);
  if (Number.isNaN(date.getTime())) return String(isoDay);
  return new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "short",
    timeZone: "UTC",
    weekday: "short",
    year: "numeric",
  })
    .format(date)
    .replace(",", "");
}

/** The plain-text twin of renderEmail, from the same paragraphs and button. */
function renderText({ paragraphs, details = [], cta }) {
  // A trusted person (a details row flagged true) gets one plain sentence.
  const trusted = details
    .filter(([, , isTrusted]) => isTrusted)
    .map(([, name]) => `${name} is a Trusted Lender on LendLoop.`);
  const link = cta?.url ? [`${cta.label}: ${cta.url}`] : [];
  return [...paragraphs, ...trusted, ...link, "- LendLoop"].join("\n\n");
}

/** A rounded label in one of EMAIL_TONES; `style` sets its size. */
function pill(label, tone, style) {
  const [background, color] = EMAIL_TONES[tone];
  return `<span style="display:inline-block;border-radius:999px;background:${background};color:${color};${style}">${escapeHtml(label)}</span>`;
}

/**
 * Renders a branded, table-based email (inline styles only, so it holds up in
 * Gmail and Outlook). Every value is escaped; links must be http(s).
 * badge: { label, tone: 'good' | 'warn' | 'bad' | 'info' }
 * details: [[label, value, isTrusted?], ...]; a trusted row gets a green
 * "Trusted lender" pill after the value; cta: { label, url } (optional)
 */
function renderEmail({
  preheader,
  badge,
  heading,
  paragraphs,
  details,
  cta,
  footnote,
}) {
  const c = EMAIL_COLORS;
  const safeUrl = HTTP_URL.test(cta?.url || "") ? cta.url : null;

  const badgeHtml = pill(
    badge.label,
    badge.tone,
    `padding:4px 10px;font:600 12px/1.4 ${SANS};letter-spacing:.04em;text-transform:uppercase;`
  );
  const body = paragraphs
    .map(
      (text) =>
        `<p style="margin:0 0 14px;font:16px/1.6 ${SANS};color:${c.text};">${escapeHtml(text)}</p>`
    )
    .join("");
  const rows = details
    .map(([label, value, isTrusted], i) => {
      const cell = `padding:10px 16px;${i ? `border-top:1px solid ${c.border};` : ""}`;
      const tagHtml = isTrusted
        ? ` ${pill(`✓ ${TRUSTED_LABEL}`, "good", `margin-left:6px;padding:2px 8px;font:600 11px/1.5 ${SANS};white-space:nowrap;`)}`
        : "";
      return `<tr>
      <td style="${cell}font:13px/1.4 ${SANS};color:${c.muted};width:96px;vertical-align:top;">${escapeHtml(label)}</td>
      <td style="${cell}font:600 14px/1.4 ${SANS};color:${c.text};word-break:break-word;">${escapeHtml(value)}${tagHtml}</td>
    </tr>`;
    })
    .join("");
  const detailsHtml = rows
    ? `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:6px 0 22px;background:${c.panel};border:1px solid ${c.border};border-radius:10px;border-collapse:separate;table-layout:fixed;">${rows}</table>`
    : "";
  const ctaHtml = safeUrl
    ? `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:4px 0 6px;"><tr>
        <td style="border-radius:8px;background:${c.primary};">
          <a href="${escapeHtml(safeUrl)}" style="display:inline-block;padding:12px 22px;font:600 15px/1 ${SANS};color:${c.onPrimary};text-decoration:none;border-radius:8px;">${escapeHtml(cta.label)} &rarr;</a>
        </td></tr></table>`
    : "";

  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light only"><title>${escapeHtml(heading)}</title></head>
<body style="margin:0;padding:0;background:${c.page};">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;">${escapeHtml(preheader)}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${c.page};">
<tr><td align="center" style="padding:32px 16px;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;">
    <tr><td style="padding:0 4px 18px;">
      <table role="presentation" cellpadding="0" cellspacing="0"><tr>
        <td style="width:32px;height:32px;border-radius:8px;background:${c.primary};color:${c.onPrimary};font:700 17px/32px ${SANS};text-align:center;">&#8635;</td>
        <td style="padding-left:10px;font:600 21px/1 ${SERIF};color:${c.text};">LendLoop</td>
      </tr></table>
    </td></tr>
    <tr><td style="background:${c.card};border:1px solid ${c.border};border-radius:14px;padding:30px 28px 26px;">
      ${badgeHtml}
      <h1 style="margin:14px 0 16px;font:600 25px/1.25 ${SERIF};color:${c.text};">${escapeHtml(heading)}</h1>
      ${body}${detailsHtml}${ctaHtml}
    </td></tr>
    <tr><td style="padding:18px 6px 0;font:13px/1.6 ${SANS};color:${c.muted};text-align:center;">
      <div style="font:italic 14px/1.6 ${SERIF};color:${c.text};">Borrow what you need. Lend what you don&rsquo;t.</div>
      <div>${escapeHtml(footnote || "You’re getting this because you lend or borrow tools on LendLoop.")}</div>
    </td></tr>
  </table>
</td></tr></table>
</body></html>`;
}
// </snippet:email-layout>

// One short email per event, using only fields in the minimized payload.
const p = $input.first().json.payload;
const who = p.recipient.firstName;
const other = p.counterpartFirstName;
const tool = p.toolName || 'tool';
const dates = p.loan.startDate === p.loan.endDate
  ? formatDay(p.loan.startDate)
  : `${formatDay(p.loan.startDate)} – ${formatDay(p.loan.endDate)}`;

// heading defaults to the subject and the button to "See your loans".
const copy = {
  'request.created': {
    subject: `${other} would like to borrow your ${tool}`,
    badge: { label: 'New request', tone: 'info' },
    intro: `${other} asked to borrow your ${tool} for ${dates}. Approve or decline it when you have a moment.`,
    cta: 'Review the request',
  },
  'request.approved': {
    subject: `Your request for the ${tool} was approved`,
    badge: { label: 'Approved', tone: 'good' },
    heading: `You're borrowing the ${tool}`,
    intro: `${other} approved your request to borrow the ${tool} for ${dates}. Arrange the pickup with them directly.`,
    cta: 'See your loan',
  },
  'request.declined': {
    subject: `Your request for the ${tool} was declined`,
    badge: { label: 'Declined', tone: 'bad' },
    heading: `The ${tool} isn't available`,
    intro: `Your request to borrow the ${tool} for ${dates} was declined. Another neighbor may have one you can borrow.`,
    cta: 'See your requests',
  },
  'request.cancelled': {
    subject: `A loan for the ${tool} was cancelled`,
    badge: { label: 'Cancelled', tone: 'warn' },
    heading: `The ${tool} loan was cancelled`,
    intro: `The loan of the ${tool} for ${dates} was cancelled.`,
  },
  'loan.returned': {
    subject: `Thanks for returning the ${tool}`,
    badge: { label: 'Returned', tone: 'good' },
    intro: `${other} marked the ${tool} as returned. Thanks for borrowing responsibly!`,
  },
  unknown: {
    subject: `LendLoop update about the ${tool}`,
    badge: { label: 'Update', tone: 'info' },
    intro: 'There is an update on one of your loans.',
  },
};
const message = copy[p.event] || copy.unknown;
const paragraphs = [`Hi ${who},`, message.intro];
const details = [
  ['Tool', tool],
  ['Dates', dates],
  ['Neighbor', other, p.counterpartIsTrustedLender],
];
const cta = { label: message.cta || 'See your loans', url: p.appUrl };

return [{
  json: {
    eventId: p.eventId,
    from: required('RESEND_FROM'),
    to: p.recipient.email,
    subject: message.subject,
    text: renderText({ paragraphs, details, cta }),
    html: renderEmail({
      preheader: message.intro,
      badge: message.badge,
      heading: message.heading || message.subject,
      paragraphs,
      details,
      cta,
    }),
  },
}];

// Tell Convex whether retrying can help: provider outages and rate limits can,
// a rejected address or payload (4xx) cannot.
const error = $input.first().json.error || {};
const text = `${error.httpCode || ''} ${error.message || ''} ${error.description || ''}`;
const status = Number((text.match(/(?:^|\D)([45]\d\d)(?:\D|$)/) || [])[1]) || 0;
const retryable = status === 0 || status >= 500 || status === 408 || status === 429;
return [{ json: { retryable, status } }];
